def t_join_repair(G_C, want_odd_set):
    cur_odd = {v for v in G_C.nodes if G_C.degree(v) % 2 == 1}
    to_fix  = cur_odd ^ want_odd_set          # symmetric difference, must have even size
    if not to_fix:
        return G_C
    K = nx.Graph()
    for u in to_fix:
        for v in to_fix:
            if u < v:
                d, path = nx.single_source_dijkstra(G_C, u, target=v, weight='len')
                K.add_edge(u, v, weight=d, path=path)
    M = nx.min_weight_matching(K, maxcardinality=True)   # exact, polynomial
    for (u, v) in M:
        # Duplicate every edge along the shortest u→v path in G_C
        path_nodes = K[u][v]['path']
        for a, b in zip(path_nodes[:-1], path_nodes[1:]):
            # pick any existing parallel edge a-b in G_C and clone it
            k0 = next(iter(G_C[a][b]))
            data = dict(G_C[a][b][k0])
            G_C.add_edge(a, b, **data)            # MultiGraph: this is a NEW key
    return G_C

def assemble_walks(Gc, junction_matchings):
    # Build the 'transition' map: for each (v, edge_key) edge-end, the partner
    # edge_key at v (or None if unpaired).
    partner = {}
    for v, (M, incident) in junction_matchings.items():
        slot_to_key = {i: incident[i][1] for i in range(len(incident))}
        for (a, b) in M:
            partner[(v, slot_to_key[a])] = slot_to_key[b]
            partner[(v, slot_to_key[b])] = slot_to_key[a]
        for i in range(len(incident)):
            partner.setdefault((v, slot_to_key[i]), None)
    # Degree-2 smooth nodes pass through trivially (only two slots).
    # Degree-1 leaves have partner=None.
    walks = []
    used = set()
    start_pool = collect_unpaired_ends(Gc, partner)
    while start_pool:
        v0, k0 = start_pool.pop()
        if (v0, k0) in used:
            continue
        walk = walk_from(v0, k0, Gc, partner, used)
        if len(walk) >= MIN_LEN_PIX:
            walks.append(walk)
    # Any edges still unused belong to a pure cycle (no unpaired starts).
    for (u, v, k, data) in Gc.edges(keys=True, data=True):
        if (u, v, k) in used or (v, u, k) in used:
            continue
        # Pure cycle: pick the topmost pixel on this cycle as start, walk
        # clockwise.
        start_pix = topmost_pixel(data['path'])
        walks.append(rotate_cycle_clockwise(walk_cycle(u, k, ...), start_pix))
    return walks

def order_walks(walks):
    def key(s):
        a = np.array(s)
        ymin = a[:,0].min();   ymax = a[:,0].max()
        xmin = a[:,1].min();   xmax = a[:,1].max()
        is_vertical = 1 if (ymax-ymin) > 1.2*(xmax-xmin) else 0
        band = ymin // BAND_PX
        return (band, -is_vertical, xmin, ymin)
    out = []
    for s in sorted(walks, key=key):
        out.append(orient(s))
    return out

def preprocess(skel):
    G_pix = build_skel_pixel_graph(skel)
    components = list(nx.connected_components(G_pix))
    motor_components = []
    for cc in components:
        Gc = G_pix.subgraph(cc).copy()
        H = nx.MultiGraph()
        specials = {n for n in Gc if Gc.degree[n] != 2}
        if not specials:                       # pure loop (o, O)
            motor_components.append(('loop', Gc))
            continue
        for s in specials:
            H.add_node(s)
        for s in specials:
            for nb in Gc.neighbors(s):
                path, length, prev, cur = [s, nb], dist(s, nb), s, nb
                while cur not in specials:
                    nxts = [x for x in Gc.neighbors(cur) if x != prev]
                    if not nxts: break
                    prev, cur = cur, nxts[0]
                    path.append(cur); length += dist(path[-2], cur)
                sig = canonical_edge_sig(path)
                if sig not in seen:
                    H.add_edge(path[0], path[-1], path=path, length=length,
                               curvature=integrated_curvature(path))
                    seen.add(sig)
        motor_components.append(('graph', H))
    return motor_components

def augment_and_walk(H, matching):
    A = H.copy()
    lift_endpoints = []
    for (u, v) in matching:
        if K[u][v]['kind'] == 'retrace':
            for e in shortest_path_edges(H, u, v):
                A.add_edge(*e, **H.edges[e], retrace=True)
        else:
            lift_endpoints.append((u, v))
    # Now A has exactly 2 * len(lift_endpoints) odd vertices (and they ARE the lift_endpoints).
    walks = []
    for (u, v) in lift_endpoints:
        if u in A and v in A and nx.has_path(A, u, v):
            walk = hierholzer_open(A, start=u, end=v)
            walks.append(walk); A.remove_edges_from(walk_edges(walk))
    # whatever remains is a union of Eulerian circuits (loops); peel them off
    while A.number_of_edges() > 0:
        start = pick_loop_start(A)             # see step 6 for bias
        walks.append(hierholzer_circuit(A, start)); A.remove_edges_from(...)
    return walks

def select_start_for_walk(walk_endpoints, kind):
    if kind == 'open':
        u, v = walk_endpoints
        # writer starts at the topmost; ties broken by leftmost
        return u if (u[0], u[1]) < (v[0], v[1]) else v
    if kind == 'loop':
        return topmost_pixel(walk)

def sort_strokes(strokes):
    def key(s):
        y0, x0 = s[0]; y1, x1 = s[-1]
        h, w = bbox_h(s), bbox_w(s)
        vertical = h > 1.2 * w
        band = s_top(s) // BAND_PX           # 60 px bands
        return (band, 0 if vertical else 1, s_left(s), s_top(s))
    return sorted(strokes, key=key)

def orient_loop(walk, script='ltr'):
    if shoelace(walk) < 0: walk = walk[::-1]   # ensure clockwise for ltr
    return rotate_to_topmost(walk)

def handle_loop(loop_pixels):
    start = topmost_then_leftmost(loop_pixels)
    walk = walk_loop(loop_pixels, start, direction='cw')
    return walk

def handle_multi_loop(H):
    # H has 0 odd vertices, cyclomatic >= 2. Pick a 'pinch point' p of highest degree;
    # decompose into Eulerian circuits each rooted at p; writer lifts between.
    p = max(H.nodes(), key=lambda n: H.degree(n))
    return decompose_into_simple_circuits(H, p)
